(function(){
 const api=window.KHALASA_API_BASE_URL||location.origin;let context=null,orderData=[],riderData=[];
 document.querySelector('.login').innerHTML='<input id="staffPhone" inputmode="numeric" placeholder="رقم الهاتف"><input id="staffAccessCode" type="password" placeholder="رمز الدخول"><button class="btn" onclick="staffCityLogin()">دخول</button>';
 window.staffToken={value:''};
 document.querySelector('.grid').insertAdjacentHTML('afterend','<section class="card" style="margin-top:16px"><div class="head"><h2>طلب إضافة شريك</h2><span>يُفعّل بعد موافقة الإدارة الرئيسية</span></div><form class="login" onsubmit="submitPartnerRequest(event)"><select id="partnerType"><option value="rider">مندوب</option><option value="merchant">محل</option></select><input id="partnerName" placeholder="الاسم" required><input id="partnerPhone" placeholder="رقم الهاتف" pattern="01[0-9]{9}" required><button class="btn">إرسال للموافقة</button></form><div id="partnerRequests"></div></section>');
 const hdr=()=>({'Content-Type':'application/json',Authorization:`Bearer ${localStorage.getItem('khalasaStaffToken')||''}`});
 const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
 const label=s=>({awaiting_merchant:'بانتظار المحل',preparing:'قيد التجهيز',awaiting_rider:'بانتظار كابتن',assigned:'تم الإسناد',picked_up:'في الطريق',delivered:'مكتمل',cancelled:'ملغي'})[s]||s;
 window.saveToken=()=>{localStorage.setItem('khalasaStaffToken',staffToken.value.trim());loadDashboard()};
 window.loadDashboard=async()=>{staffToken.value=localStorage.getItem('khalasaStaffToken')||'';try{const c=await fetch(`${api}/v1/city-admin/context`,{headers:hdr()});if(!c.ok)throw Error();context=await c.json();if(context.city){cityName.textContent=context.city.name;cityGovernorate.textContent=context.city.governorate}const [o,r]=await Promise.all([fetch(`${api}/v1/city-admin/orders`,{headers:hdr()}),fetch(`${api}/v1/city-admin/riders`,{headers:hdr()})]);orderData=o.ok?(await o.json()).orders||[]:[];riderData=r.ok?(await r.json()).riders||[]:[];notice.className='notice ok';notice.textContent=context.unrestricted?'دخول مدير رئيسي — عرض غير مقيد.':'متصل وآمن — البيانات مقيدة بمدينة المستخدم على الخادم.';render();}catch(e){notice.className='notice';notice.textContent='تعذر تسجيل الدخول. تأكد من رمز المستخدم ومن نشر تحديث الخادم.';}};
 function render(){const active=orderData.filter(x=>!['delivered','cancelled'].includes(x.status));activeCount.textContent=active.length;waitingCount.textContent=orderData.filter(x=>x.status==='awaiting_rider').length;riderCount.textContent=riderData.filter(x=>x.is_available).length;const canAssign=context.unrestricted||context.permissions?.['orders.manage'],canRiders=context.unrestricted||context.permissions?.['riders.manage'];orders.innerHTML=orderData.length?orderData.map(x=>`<article class="order"><div><b>${esc(x.public_code||x.id)}</b><small>${esc(x.merchant_name||'المحل')} · ${esc(x.customer_name||'العميل')}</small><span class="badge">${esc(label(x.status))}</span></div>${x.status==='awaiting_rider'?`<div><select id="assign-${esc(x.id)}">${riderData.filter(r=>r.is_available).map(r=>`<option value="${esc(r.id)}">${esc(r.full_name)}</option>`).join('')}</select><button class="btn" ${canAssign?'':'disabled'} data-assign-order="${esc(x.id)}">إسناد</button></div>`:''}</article>`).join(''):'<p>لا توجد طلبات في هذه المدينة.</p>';orders.querySelectorAll('[data-assign-order]').forEach(button=>button.onclick=()=>assignRider(button.dataset.assignOrder));riders.innerHTML=riderData.length?riderData.map(r=>`<article class="rider"><div><b>${esc(r.full_name)}</b><small>${esc(r.vehicle_type||'دراجة')} · ${esc(r.phone)}</small></div><button class="btn" ${canRiders?'':'disabled'} data-rider="${esc(r.id)}" data-available="${!r.is_available}"><span class="badge ${r.is_available?'':'off'}">${r.is_available?'متاح':'غير متاح'}</span></button></article>`).join(''):'<p>لا يوجد كباتن مسجلون في هذه المدينة.</p>';riders.querySelectorAll('[data-rider]').forEach(button=>button.onclick=()=>setAvailability(button.dataset.rider,button.dataset.available==='true'))}
 window.assignRider=async id=>{const select=document.getElementById(`assign-${id}`);if(!select||!select.value)return alert('لا يوجد كابتن متاح.');const r=await fetch(`${api}/v1/city-admin/orders/${id}/assign`,{method:'POST',headers:hdr(),body:JSON.stringify({riderId:select.value})});if(!r.ok)alert('تعذر الإسناد؛ تحقق من حالة الطلب والكابتن.');loadDashboard()};
 window.setAvailability=async(id,isAvailable)=>{const r=await fetch(`${api}/v1/city-admin/riders/${id}/availability`,{method:'PATCH',headers:hdr(),body:JSON.stringify({isAvailable})});if(!r.ok)alert('لا توجد صلاحية أو أن الكابتن غير معتمد.');loadDashboard()};
 window.staffCityLogin=async()=>{const r=await fetch(`${api}/v1/staff/login`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({phone:staffPhone.value.trim(),accessCode:staffAccessCode.value})});if(!r.ok)return alert('بيانات الدخول غير صحيحة.');const data=await r.json();if(data.user.role!=='city_admin')return alert('هذا الحساب ليس مشرف مدينة.');localStorage.setItem('khalasaStaffToken',data.token);loadDashboard();loadPartnerRequests()};
 window.submitPartnerRequest=async e=>{e.preventDefault();const r=await fetch(`${api}/v1/city-admin/partner-requests`,{method:'POST',headers:hdr(),body:JSON.stringify({partnerType:partnerType.value,fullName:partnerName.value.trim(),phone:partnerPhone.value.trim()})});if(!r.ok)return alert('تعذر إرسال الطلب أو لا توجد صلاحية.');e.target.reset();alert('تم إرسال الطلب للإدارة الرئيسية للموافقة.');loadPartnerRequests()};
 async function loadPartnerRequests(){const r=await fetch(`${api}/v1/city-admin/partner-requests`,{headers:hdr()});if(!r.ok)return;const data=await r.json();partnerRequests.innerHTML=(data.requests||[]).map(x=>`<p><b>${esc(x.full_name)}</b> — ${x.partner_type==='rider'?'مندوب':'محل'} — <span class="badge">${x.status==='pending'?'بانتظار الموافقة':x.status==='approved'?'مقبول':'مرفوض'}</span></p>`).join('')};loadDashboard();loadPartnerRequests();
})();
